# Plan

**Tier 2 (Representation & Components).** The stuck point is 0.7527 with a TabM+GBDT blend that already has a reasonable weight search; the MLP branch is essentially `(base numerics + 3 TE columns) -> 2 blocks`. The real headroom is *representation*: this is a low-cardinality categorical dataset (≤25 levels/col) where GBDT's advantage comes from rich interaction splits, while the MLP only sees three TE combos and 38 base features. I will:

1. **Add a proper categorical embedding path** — encode every nominal/freq/bin column as an integer index and feed it through `nn.Embedding` (dims 4–8), concatenated with the existing standardized numerics. This lets the MLP learn interactions the TE-3 summary cannot express, matching the inductive bias of the data.
2. **Expand categorical-interaction TE sources** to include `coupon_marital`, `coupon_direction`, `coupon_distance`, `coupon_expiration`, `coupon_age` (all already computed in `_combos`), fitted OOF as today — no leakage.
3. **Increase TabM capacity modestly** (`hidden=192, heads=6, dropout=0.2`) and switch to a 3-seed bag inside each fold for the MLP so variance drops without new architectures.
4. **Keep the GBDT anchor** but let it use the same expanded interaction columns via `GBDTFeatureEncoder` (it already iterates `_INTERACTION_CATS`), and **re-fit the blend weight by fine grid on OOF** over the expanded OOF signal.

No change to the CLI, output format, or metric. Everything (encoders, TE maps, embedding tables) is persisted to `--model` and loaded read-only during predict.

**Why this breaks the plateau:** the current MLP is starved of categorical structure — it must reconstruct 20-way interactions from three scalar TE summaries. Adding embeddings is a *systemic representation* upgrade with the same evaluation and interaction with the existing blend, so the higher-capacity MLP should beat the GBDT alone and lift the blend, not just re-weight tunables.

Now implement it.

```python
"""In-vehicle coupon acceptance — embedding-augmented TabM + GBDT ensemble.

CLI:
    python solution.py train   --data /data --model /model
    python solution.py predict --data /data --model /model --output /output/predictions.csv
"""

from __future__ import annotations

import argparse
import json
import math
import os
import pickle
import time
from typing import Any, Dict, List, Optional, Sequence, Tuple

import numpy as np
import pandas as pd
from sklearn.model_selection import StratifiedKFold

import torch
import torch.nn as nn

torch.set_num_threads(2)

# =========================================================================== #
# Step 1: data processing & feature engineering
# =========================================================================== #
TARGET_COL = "label"
ROW_ID_COL = "row_id"

NOMINAL_CATS: List[str] = [
    "time", "coupon", "expiration", "gender", "maritalStatus",
    "education", "occupation", "income",
]
FREQ_COLS: List[str] = [
    "Bar", "CoffeeHouse", "CarryAway", "RestaurantLessThan20", "Restaurant20To50",
]
BIN_INT_COLS: List[str] = [
    "has_children", "toCoupon_GEQ5min", "toCoupon_GEQ15min",
    "toCoupon_GEQ25min", "direction_same", "direction_opp",
]

# Expanded TE sources (all exist in FeatureEngineer._combos).
TE_SOURCES: List[str] = [
    "coupon_occupation", "coupon_income", "coupon_time",
    "coupon_marital", "coupon_direction", "coupon_distance",
    "coupon_expiration", "coupon_age",
]

AGE_N = {"under21": 0, "21": 1, "26": 2, "31": 3, "36": 4, "41": 5, "46": 6, "50plus": 7}
INCOME_N = {
    "lessthan$12500": 0.5, "$12500-$24999": 18.75, "$25000-$37499": 31.25,
    "$37500-$49999": 43.75, "$50000-$62499": 56.25, "$62500-$74999": 68.75,
    "$75000-$87499": 81.25, "$87500-$99999": 93.75, "$100000ormore": 110.0,
}
EDU_N = {
    "somehighschool": 0, "highschoolgraduate": 1, "somecollege-nodegree": 2,
    "associatesdegree": 3, "bachelorsdegree": 4, "graduatedegree": 5,
}
TIME_N = {"7am": 7, "10am": 10, "2pm": 14, "6pm": 18, "10pm": 22}
EXP_N = {"2h": 2.0, "1d": 24.0}
FREQ_N = {"never": 0, "less1": 1, "1~3": 2, "4~8": 3, "gt8": 4}


def _norm(v: Any) -> str:
    if v is None:
        return ""
    if isinstance(v, float) and np.isnan(v):
        return ""
    return str(v).strip().lower().replace(" ", "")


def load_schema(data_dir: str) -> Dict[str, Any]:
    with open(os.path.join(data_dir, "schema.json"), "r", encoding="utf-8") as fh:
        return json.load(fh)


def _read_features(data_dir: str, schema: Dict[str, Any]) -> pd.DataFrame:
    feats = pd.read_csv(os.path.join(data_dir, "features.csv"))
    cols = schema.get("feature_columns")
    if cols:
        missing = [c for c in cols if c not in feats.columns]
        if missing:
            raise ValueError(f"features.csv missing schema columns: {missing}")
        feats = feats[cols].copy()
    return feats.reset_index(drop=True)


def load_train_data(data_dir: str) -> Tuple[pd.DataFrame, np.ndarray, Dict[str, Any]]:
    schema = load_schema(data_dir)
    feats = _read_features(data_dir, schema)
    labels = pd.read_csv(os.path.join(data_dir, "labels.csv"))
    y_raw = labels[TARGET_COL] if TARGET_COL in labels.columns else labels.iloc[:, 0]
    n = min(len(feats), len(y_raw))
    feats = feats.iloc[:n].reset_index(drop=True)
    y_raw = y_raw.iloc[:n].reset_index(drop=True)
    classes = pd.unique(y_raw.astype(str))
    try:
        classes = sorted(classes, key=lambda s: float(s))
    except (TypeError, ValueError):
        classes = sorted(classes)
    label_to_idx = {c: i for i, c in enumerate(classes)}
    y = y_raw.astype(str).map(label_to_idx).to_numpy(dtype=np.int64)
    schema = dict(schema)
    schema["label_classes"] = classes
    return feats, y, schema


def load_predict_data(data_dir: str) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    schema = load_schema(data_dir)
    return _read_features(data_dir, schema), schema


def get_cv_splits(y: np.ndarray, n_splits: int = 5, random_state: int = 42):
    skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=random_state)
    return [(tr, va) for tr, va in skf.split(np.zeros(len(y)), y)]


# ------------------------------------------------------------------ base FE #
def _base_features(df: pd.DataFrame) -> pd.DataFrame:
    b = pd.DataFrame(index=np.arange(len(df)))
    b["temperature"] = pd.to_numeric(df["temperature"], errors="coerce")
    for c in BIN_INT_COLS:
        if c in df.columns:
            b[c] = pd.to_numeric(df[c], errors="coerce")
    b["age_num"] = df["age"].map(lambda v: AGE_N.get(_norm(v), np.nan))
    b["income_num"] = df["income"].map(lambda v: INCOME_N.get(_norm(v), np.nan))
    b["education_num"] = df["education"].map(lambda v: EDU_N.get(_norm(v), np.nan))
    b["time_hour"] = df["time"].map(lambda v: TIME_N.get(_norm(v), np.nan))
    b["expiration_hours"] = df["expiration"].map(lambda v: EXP_N.get(_norm(v), np.nan))

    hour = b["time_hour"]
    b["is_morning"] = ((hour >= 7) & (hour < 12)).astype(float)
    b["is_lunch"] = (hour == 14).astype(float)
    b["is_evening"] = (hour >= 18).astype(float)

    freq_vals = {}
    for c in FREQ_COLS:
        if c in df.columns:
            vals = df[c].map(lambda v: FREQ_N.get(_norm(v), np.nan))
            freq_vals[c] = vals
            b[c + "_ord"] = vals.fillna(-1.0)
    if freq_vals:
        stacked = pd.concat(freq_vals.values(), axis=1)
        b["freq_sum"] = stacked.sum(axis=1, skipna=True).fillna(0.0)
        b["freq_known"] = stacked.notna().sum(axis=1).astype(float)
        b["freq_missing"] = stacked.isna().sum(axis=1).astype(float)

    g15 = b.get("toCoupon_GEQ15min", pd.Series(0.0, index=b.index)).fillna(1.0)
    g25 = b.get("toCoupon_GEQ25min", pd.Series(0.0, index=b.index)).fillna(1.0)
    b["distance_est"] = np.where(g15 <= 0, 5.0, np.where(g25 <= 0, 15.0, 25.0))
    b["near_coupon"] = (b["distance_est"] <= 5.0).astype(float)

    cp = df["coupon"].map(_norm)
    b["is_bar"] = cp.eq("bar").astype(float)
    b["is_coffee"] = cp.str.contains("coffee", na=False).astype(float)
    b["is_restaurant"] = cp.str.contains("restaurant", na=False).astype(float)
    b["is_carryout"] = cp.str.contains("carry", na=False).astype(float)
    b["is_cheap_restaurant"] = cp.eq("restaurant(<20)").astype(float)

    b["income_x_children"] = b["income_num"] * b.get(
        "has_children", pd.Series(0.0, index=b.index)
    ).fillna(0.0)
    b["freq_per_distance"] = b["freq_sum"] / (1.0 + b["distance_est"])
    return b


def _combo_frame(df: pd.DataFrame) -> pd.DataFrame:
    def s(name: str) -> pd.Series:
        if name not in df.columns:
            return pd.Series(["__NA__"] * len(df), index=np.arange(len(df)))
        return df[name].astype(str).fillna("__NA__").reset_index(drop=True)

    coupon = s("coupon")
    out = pd.DataFrame(index=np.arange(len(df)))
    out["coupon"] = coupon
    out["occupation"] = s("occupation")
    out["time"] = s("time")
    out["coupon_time"] = coupon + "|" + s("time")
    out["coupon_expiration"] = coupon + "|" + s("expiration")
    out["coupon_marital"] = coupon + "|" + s("maritalStatus")
    out["coupon_children"] = coupon + "|" + s("has_children")
    out["coupon_income"] = coupon + "|" + s("income")
    out["coupon_age"] = coupon + "|" + s("age")
    out["coupon_occupation"] = coupon + "|" + s("occupation")

    g15 = pd.to_numeric(df["toCoupon_GEQ15min"], errors="coerce") if "toCoupon_GEQ15min" in df.columns else pd.Series([1.0]*len(df))
    g25 = pd.to_numeric(df["toCoupon_GEQ25min"], errors="coerce") if "toCoupon_GEQ25min" in df.columns else pd.Series([1.0]*len(df))
    g15 = g15.fillna(1.0).reset_index(drop=True).to_numpy()
    g25 = g25.fillna(1.0).reset_index(drop=True).to_numpy()
    dist = np.where(g15 <= 0, "5", np.where(g25 <= 0, "15", "25"))
    out["coupon_distance"] = coupon.to_numpy() + "|" + dist.astype(str)
    out["coupon_direction"] = coupon + "|" + s("direction_opp")
    return out


# ------------------------------------------------------- FeatureEngineer #
class FeatureEngineer:
    """Leakage-safe feature pipeline with OOF target encoding."""

    def __init__(self, te_sources=None, smooth=20.0, n_splits=5,
                 random_state=42, scale=True):
        self.te_sources = list(te_sources if te_sources is not None else TE_SOURCES)
        self.smooth = float(smooth)
        self.n_splits = int(n_splits)
        self.random_state = int(random_state)
        self.scale = bool(scale)
        self.prior_: float = 0.0
        self.base_cols_: List[str] = []
        self.te_maps_: Dict[str, Dict[str, float]] = {}
        self.feature_names_: List[str] = []
        self.base_medians_: pd.Series = pd.Series(dtype=float)
        self.mean_ = np.zeros(0, dtype=np.float64)
        self.std_ = np.ones(0, dtype=np.float64)

    def _te_map(self, keys: pd.Series, y: np.ndarray) -> Dict[str, float]:
        frame = pd.DataFrame({"k": keys.astype(str).to_numpy(), "y": np.asarray(y)})
        agg = frame.groupby("k")["y"].agg(["sum", "count"])
        smoothed = (agg["sum"] + self.prior_ * self.smooth) / (agg["count"] + self.smooth)
        return {str(k): float(v) for k, v in smoothed.items()}

    def _apply_te(self, combos, maps):
        data = {}
        for name in self.te_sources:
            mapping = maps.get(name, {})
            data["te_" + name] = combos[name].map(mapping).fillna(self.prior_).to_numpy(dtype=np.float64)
        return pd.DataFrame(data)

    def _fill_base(self, base: pd.DataFrame) -> pd.DataFrame:
        med = getattr(self, "base_medians_", None)
        if med is not None and len(med) > 0:
            base = base.fillna(med)
        return base.fillna(0.0)

    def _transform_raw(self, df: pd.DataFrame) -> pd.DataFrame:
        base = self._fill_base(_base_features(df))
        combos = _combo_frame(df)
        te = self._apply_te(combos, self.te_maps_)
        raw = pd.concat([base.reset_index(drop=True), te.reset_index(drop=True)], axis=1)
        cols = self.feature_names_ or list(raw.columns)
        return raw.reindex(columns=cols, fill_value=0.0)

    def _scale_frame(self, raw: pd.DataFrame) -> pd.DataFrame:
        if not self.scale:
            return raw.reset_index(drop=True)
        arr = raw.to_numpy(dtype=np.float64)
        arr = (arr - self.mean_[None, :]) / self.std_[None, :]
        arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
        return pd.DataFrame(arr, columns=list(self.feature_names_))

    def fit(self, df: pd.DataFrame, y: np.ndarray) -> "FeatureEngineer":
        y = np.asarray(y, dtype=np.float64).ravel()
        self.prior_ = float(np.clip(y.mean(), 1e-6, 1.0 - 1e-6))
        base = _base_features(df)
        self.base_medians_ = base.median(numeric_only=True).fillna(0.0)
        base = self._fill_base(base)
        self.base_cols_ = list(base.columns)
        combos = _combo_frame(df)
        self.te_maps_ = {n: self._te_map(combos[n], y) for n in self.te_sources}
        self.feature_names_ = self.base_cols_ + ["te_" + n for n in self.te_sources]
        raw = self._transform_raw(df)
        arr = raw.to_numpy(dtype=np.float64)
        if self.scale:
            self.mean_ = arr.mean(axis=0)
            self.std_ = arr.std(axis=0)
            self.std_[self.std_ < 1e-8] = 1.0
        else:
            self.mean_ = np.zeros(arr.shape[1]); self.std_ = np.ones(arr.shape[1])
        return self

    def fit_transform(self, df: pd.DataFrame, y: np.ndarray) -> pd.DataFrame:
        y_arr = np.asarray(y, dtype=np.float64).ravel()
        self.fit(df, y_arr)
        combos = _combo_frame(df)
        oof = np.full((len(df), len(self.te_sources)), self.prior_, dtype=np.float64)
        if len(np.unique(y_arr)) > 1 and self.n_splits > 1:
            skf = StratifiedKFold(n_splits=self.n_splits, shuffle=True, random_state=self.random_state)
            for tr, va in skf.split(np.zeros(len(y_arr)), y_arr):
                fold_maps = {n: self._te_map(combos[n].iloc[tr], y_arr[tr]) for n in self.te_sources}
                for j, n in enumerate(self.te_sources):
                    oof[va, j] = combos[n].iloc[va].map(fold_maps[n]).fillna(self.prior_).to_numpy(dtype=np.float64)
        raw = self._transform_raw(df).copy()
        raw[["te_" + n for n in self.te_sources]] = oof
        return self._scale_frame(raw)

    def transform(self, df: pd.DataFrame) -> pd.DataFrame:
        raw = self._transform_raw(df)
        return self._scale_frame(raw)


