class CatEncoder:
    """Deterministic integer encoder for all categorical columns."""

    def __init__(self):
        self.maps_: Dict[str, Dict[str, int]] = {}
        self.cols_: List[str] = []
        self.cards_: List[int] = []

    @staticmethod
    def _raw_levels(df: pd.DataFrame) -> pd.DataFrame:
        cols = list(NOMINAL_CATS) + list(FREQ_COLS) + list(BIN_INT_COLS) + ["temperature"]
        combos = _combo_frame(df)
        for c in ["coupon_time", "coupon_expiration", "coupon_marital",
                  "coupon_children", "coupon_income", "coupon_age",
                  "coupon_distance", "coupon_direction", "coupon_occupation"]:
            cols.append(c)
        out = pd.DataFrame(index=np.arange(len(df)))
        for c in cols:
            if c in combos.columns:
                out[c] = combos[c].astype(str).fillna("__NA__").to_numpy()
            elif c in df.columns:
                out[c] = df[c].astype(str).fillna("__NA__").to_numpy()
            else:
                out[c] = "__NA__"
        return out

    def fit(self, df: pd.DataFrame) -> "CatEncoder":
        levels = self._raw_levels(df)
        self.cols_ = list(levels.columns)
        self.maps_ = {}
        self.cards_ = []
        for c in self.cols_:
            uniq = sorted(levels[c].unique().tolist())
            self.maps_[c] = {u: i + 1 for i, u in enumerate(uniq)}  # 0 = unknown
            self.cards_.append(len(uniq) + 1)
        return self

    def transform(self, df: pd.DataFrame) -> np.ndarray:
        levels = self._raw_levels(df)
        n = len(df)
        out = np.zeros((n, len(self.cols_)), dtype=np.int64)
        for j, c in enumerate(self.cols_):
            vals = levels[c] if c in levels.columns else pd.Series(["__NA__"] * n)
            out[:, j] = vals.map(self.maps_[c]).fillna(0).astype(np.int64).to_numpy()
        return out


