    return feats, y, schema


def load_predict_data(data_dir):
    schema = load_schema(data_dir)
    return _read_features(data_dir, schema), schema


def get_cv_splits(y, n_splits=5, random_state=42):
    skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=random_state)
    return [(tr, va) for tr, va in skf.split(np.zeros(len(y)), y)]


def _base_features(df):
    b = pd.DataFrame(index=np.arange(len(df)))
    b["temperature"] = pd.to_numeric(df["temperature"], errors="coerce")
    for c in BIN_INT_COLS:
        if c in df.columns:
            b[c] = pd.to_numeric(df[c], errors="coerce")
    b["age_num"] = df["age"].map(lambda v: AGE_N.get(_norm(v), np.nan))
    b["income_num"] = df["income"].map(lambda v: INCOME_N.get(_norm(v), np.nan))
    b["education_num"] = df["education"].map(lambda v: EDU_N.get(_norm(v), np.nan))
    b["time_hour"] = df["time"].map(lambda v: TIME_N.get(_norm(v), np.nan))
    b["expiration_hours"] = df["expiration"].map(lambda v: EXP_N.get(_norm(v), np.nan))
    hour = b["time_hour"]
    b["is_morning"] = ((hour >= 7) & (hour < 12)).astype(float)
    b["is_lunch"] = (hour == 14).astype(float)
    b["is_evening"] = (hour >= 18).astype(float)
    freq_vals = {}
    for c in FREQ_COLS:
        if c in df.columns:
            vals = df[c].map(lambda v: FREQ_N.get(_norm(v), np.nan))
            freq_vals[c] = vals
            b[c + "_ord"] = vals.fillna(-1.0)
    if freq_vals:
        stacked = pd.concat(freq_vals.values(), axis=1)
        b["freq_sum"] = stacked.sum(axis=1, skipna=True).fillna(0.0)
        b["freq_known"] = stacked.notna().sum(axis=1).astype(float)
        b["freq_missing"] = stacked.isna().sum(axis=1).astype(float)
    g15 = b.get("toCoupon_GEQ15min", pd.Series(0.0, index=b.index)).fillna(1.0)
    g25 = b.get("toCoupon_GEQ25min", pd.Series(0.0, index=b.index)).fillna(1.0)
    b["distance_est"] = np.where(g15 <= 0, 5.0, np.where(g25 <= 0, 15.0, 25.0))
    b["near_coupon"] = (b["distance_est"] <= 5.0).astype(float)
    cp = df["coupon"].map(_norm)
    b["is_bar"] = cp.eq("bar").astype(float)
    b["is_coffee"] = cp.str.contains("coffee", na=False).astype(float)
    b["is_restaurant"] = cp.str.contains("restaurant", na=False).astype(float)
    b["is_carryout"] = cp.str.contains("carry", na=False).astype(float)
    b["is_cheap_restaurant"] = cp.eq("restaurant(<20)").astype(float)
    b["income_x_children"] = b["income_num"] * b.get(
        "has_children", pd.Series(0.0, index=b.index)).fillna(0.0)
    b["freq_per_distance"] = b["freq_sum"] / (1.0 + b["distance_est"])
    return b


def _combo_frame(df):
    def s(name):
        if name not in df.columns:
            return pd.Series(["__NA__"] * len(df), index=np.arange(len(df)))
        return df[name].astype(str).fillna("__NA__").reset_index(drop=True)
    coupon = s("coupon")
    out = pd.DataFrame(index=np.arange(len(df)))
    out["coupon"] = coupon
    out["occupation"] = s("occupation")
    out["time"] = s("time")
    out["coupon_time"] = coupon + "|" + s("time")
    out["coupon_expiration"] = coupon + "|" + s("expiration")
    out["coupon_marital"] = coupon + "|" + s("maritalStatus")
    out["coupon_children"] = coupon + "|" + s("has_children")
    out["coupon_income"] = coupon + "|" + s("income")
    out["coupon_age"] = coupon + "|" + s("age")
    out["coupon_occupation"] = coupon + "|" + s("occupation")
    g15 = pd.to_numeric(df["toCoupon_GEQ15min"], errors="coerce") if "toCoupon_GEQ15min" in df.columns else pd.Series([1.0] * len(df))
    g25 = pd.to_numeric(df["toCoupon_GEQ25min"], errors="coerce") if "toCoupon_GEQ25min" in df.columns else pd.Series([1.0] * len(df))
    g15 = g15.fillna(1.0).reset_index(drop=True).to_numpy()
    g25 = g25.fillna(1.0).reset_index(drop=True).to_numpy()
    dist = np.where(g15 <= 0, "5", np.where(g25 <= 0, "15", "25"))
    out["coupon_distance"] = coupon.to_numpy() + "|" + dist.astype(str)
    out["coupon_direction"] = coupon + "|" + s("direction_opp")
    return out


class FeatureEngineer:
    def __init__(self, te_sources=None, smooth=20.0, n_splits=5,
                 random_state=42, scale=True):
        self.te_sources = list(te_sources if te_sources is not None else TE_SOURCES)
        self.smooth = float(smooth)
        self.n_splits = int(n_splits)
        self.random_state = int(random_state)
        self.scale = bool(scale)
        self.prior_ = 0.0
        self.base_cols_ = []
        self.te_maps_ = {}
        self.feature_names_ = []
        self.base_medians_ = pd.Series(dtype=float)
        self.mean_ = np.zeros(0)
        self.std_ = np.ones(0)

    def _te_map(self, keys, y):
        frame = pd.DataFrame({"k": keys.astype(str).to_numpy(), "y": np.asarray(y)})
        agg = frame.groupby("k")["y"].agg(["sum", "count"])
        smoothed = (agg["sum"] + self.prior_ * self.smooth) / (agg["count"] + self.smooth)
        return {str(k): float(v) for k, v in smoothed.items()}

    def _apply_te(self, combos, maps):
        data = {}
        for n in self.te_sources:
            m = maps.get(n, {})
            data["te_" + n] = combos[n].map(m).fillna(self.prior_).to_numpy(dtype=np.float64)
        return pd.DataFrame(data)

    def _fill_base(self, base):
        med = getattr(self, "base_medians_", None)
        if med is not None and len(med) > 0:
            base = base.fillna(med)
        return base.fillna(0.0)

    def _transform_raw(self, df):
        base = self._fill_base(_base_features(df))
        combos = _combo_frame(df)
        te = self._apply_te(combos, self.te_maps_)
        raw = pd.concat([base.reset_index(drop=True), te.reset_index(drop=True)], axis=1)
        cols = self.feature_names_ or list(raw.columns)
        return raw.reindex(columns=cols, fill_value=0.0)

    def _scale_frame(self, raw):
        if not self.scale:
            return raw.reset_index(drop=True)
        arr = raw.to_numpy(dtype=np.float64)
        arr = (arr - self.mean_[None, :]) / self.std_[None, :]
        arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
        return pd.DataFrame(arr, columns=list(self.feature_names_))

    def fit(self, df, y):
        y = np.asarray(y, dtype=np.float64).ravel()
        self.prior_ = float(np.clip(y.mean(), 1e-6, 1.0 - 1e-6))
        base = _base_features(df)
        self.base_medians_ = base.median(numeric_only=True).fillna(0.0)
        base = self._fill_base(base)
        self.base_cols_ = list(base.columns)
        combos = _combo_frame(df)
        self.te_maps_ = {n: self._te_map(combos[n], y) for n in self.te_sources}
        self.feature_names_ = self.base_cols_ + ["te_" + n for n in self.te_sources]
        raw = self._transform_raw(df)
        arr = raw.to_numpy(dtype=np.float64)
        if self.scale:
            self.mean_ = arr.mean(axis=0)
            self.std_ = arr.std(axis=0)
            self.std_[self.std_ < 1e-8] = 1.0
        else:
            self.mean_ = np.zeros(arr.shape[1]); self.std_ = np.ones(arr.shape[1])
        return self

    def fit_transform(self, df, y):
        y_arr = np.asarray(y, dtype=np.float64).ravel()
        self.fit(df, y_arr)
        combos = _combo_frame(df)
        oof = np.full((len(df), len(self.te_sources)), self.prior_, dtype=np.float64)
        if len(np.unique(y_arr)) > 1 and self.n_splits > 1:
            skf = StratifiedKFold(n_splits=self.n_splits, shuffle=True, random_state=self.random_state)
            for tr, va in skf.split(np.zeros(len(y_arr)), y_arr):
                fold_maps = {n: self._te_map(combos[n].iloc[tr], y_arr[tr]) for n in self.te_sources}
                for j, n in enumerate(self.te_sources):
                    oof[va, j] = combos[n].iloc[va].map(fold_maps[n]).fillna(self.prior_).to_numpy(dtype=np.float64)
        raw = self._transform_raw(df).copy()
        raw[["te_" + n for n in self.te_sources]] = oof
        return self._scale_frame(raw)

    def transform(self, df):
        return self._scale_frame(self._transform_raw(df))


class CatEncoder:
    def __init__(self):
        self.maps_ = {}
        self.cols_ = []
        self.cards_ = []

    @staticmethod
    def _raw_levels(df):
        cols = list(NOMINAL_CATS) + list(FREQ_COLS) + list(BIN_INT_COLS) + ["temperature"] + list(INTERACTION_CATS)
        combos = _combo_frame(df)
        out = pd.DataFrame(index=np.arange(len(df)))
        for c in cols:
            if c in combos.columns:
                out[c] = combos[c].astype(str).fillna("__NA__").to_numpy()
            elif c in df.columns:
                out[c] = df[c].astype(str).fillna("__NA__").to_numpy()
            else:
                out[c] = "__NA__"
        return out

    def fit(self, df):
        levels = self._raw_levels(df)
        self.cols_ = list(levels.columns)
        self.maps_ = {}
        self.cards_ = []
        for c in self.cols_:
            uniq = sorted(levels[c].unique().tolist())
            self.maps_[c] = {u: i + 1 for i, u in enumerate(uniq)}
            self.cards_.append(len(uniq) + 1)
        return self

    def transform(self, df):
        levels = self._raw_levels(df)
        n = len(df)
        out = np.zeros((n, len(self.cols_)), dtype=np.int64)
        for j, c in enumerate(self.cols_):
            vals = levels[c] if c in levels.columns else pd.Series(["__NA__"] * n)
            out[:, j] = vals.map(self.maps_[c]).fillna(0).astype(np.int64).to_numpy()
        return out


class GBDTFeatureEncoder:
    def __init__(self):
        self.ordinal_maps_ = {}
        self.medians_ = {}
        self.feature_names_ = []
        self.cat_mask_ = np.zeros(0, dtype=bool)

    def _cols(self):
        cols = list(NOMINAL_CATS) + list(FREQ_COLS) + list(BIN_INT_COLS) + ["temperature"]
        cols += ["age_num", "income_num", "education_num", "time_hour", "expiration_hours",
                 "is_morning", "is_lunch", "is_evening", "freq_sum", "freq_known",
                 "freq_missing", "distance_est", "near_coupon", "is_bar", "is_coffee",
                 "is_restaurant", "is_carryout", "is_cheap_restaurant",
                 "income_x_children", "freq_per_distance"]
        cols += [c + "_ord" for c in FREQ_COLS]
        cols += list(INTERACTION_CATS)
        seen, out = set(), []
        for c in cols:
            if c not in seen:
                seen.add(c); out.append(c)
        return out

    def fit(self, df):
        cols = self._cols()
        interaction_set = set(INTERACTION_CATS)
        cat_cols = set(NOMINAL_CATS) | set(FREQ_COLS) | interaction_set
        eng = _base_features(df)
        eng_cols = set(eng.columns)
        combos = _combo_frame(df)
        self.ordinal_maps_, self.medians_ = {}, {}
        self.feature_names_ = list(cols)
        mask = []
        for c in cols:
            if c in cat_cols:
                if c in interaction_set and c in combos.columns:
                    levels = sorted(combos[c].astype(str).fillna("__NA__").unique().tolist())
                elif c in df.columns:
                    levels = sorted(df[c].astype(str).fillna("__NA__").unique().tolist())
                else:
                    levels = []
                self.ordinal_maps_[c] = {lvl: i + 1 for i, lvl in enumerate(levels)}
                mask.append(True)
            elif c in eng_cols:
                num = pd.to_numeric(eng[c], errors="coerce")
                self.medians_[c] = float(num.median()) if num.notna().any() else 0.0
                mask.append(False)
            else:
                if c in df.columns:
                    num = pd.to_numeric(df[c], errors="coerce")
                    self.medians_[c] = float(num.median()) if num.notna().any() else 0.0
                else:
                    self.medians_[c] = 0.0
                mask.append(False)
        self.cat_mask_ = np.asarray(mask, dtype=bool)
        return self

    def transform(self, df):
        n = len(df)
        eng = _base_features(df)
        eng_cols = set(eng.columns)
        interaction_set = set(INTERACTION_CATS)
        combos = _combo_frame(df)
        arr = np.zeros((n, len(self.feature_names_)), dtype=np.float64)
        for j, c in enumerate(self.feature_names_):
            if c in self.ordinal_maps_:
                if c in interaction_set and c in combos.columns:
                    vals = combos[c].astype(str).fillna("__NA__")
                elif c in df.columns:
                    vals = df[c].astype(str).fillna("__NA__")
                else:
                    vals = pd.Series(["__NA__"] * n)
                arr[:, j] = vals.map(self.ordinal_maps_[c]).fillna(0).to_numpy(dtype=np.float64)
            elif c in eng_cols:
                num = pd.to_numeric(eng[c], errors="coerce").fillna(self.medians_.get(c, 0.0))
                arr[:, j] = num.to_numpy(dtype=np.float64)
            else:
                if c in df.columns:
                    num = pd.to_numeric(df[c], errors="coerce")
                else:
                    num = pd.Series([np.nan] * n)
                arr[:, j] = num.fillna(self.medians_.get(c, 0.0)).to_numpy(dtype=np.float64)
        return arr


# =========================================================================== #
# Step 2: Embedding-augmented TabM
# =========================================================================== #
class TabMRank1Block(nn.Module):
    def __init__(self, hidden, num_heads, dropout):
        super().__init__()
        self.W = nn.Parameter(torch.empty(hidden, hidden))
        self.b = nn.Parameter(torch.zeros(hidden))
        nn.init.kaiming_uniform_(self.W, a=math.sqrt(5))
        nn.init.zeros_(self.b)
        scale = 1.0 / math.sqrt(hidden)
        self.U = nn.Parameter(torch.randn(num_heads, hidden, 1) * scale)
        self.V = nn.Parameter(torch.randn(num_heads, 1, hidden) * scale)
        self.ln = nn.LayerNorm(hidden)
        self.act = nn.GELU()
        self.dropout = nn.Dropout(dropout)

    def forward(self, x):
        K, B, H = x.shape
        W_eff = self.W.unsqueeze(0) + torch.bmm(self.U, self.V)
        h = torch.baddbmm(self.b.view(1, 1, -1).expand(K, B, -1), x, W_eff.transpose(-2, -1))
        h = self.dropout(self.act(h))
        return self.ln(h + x)


class TabM(nn.Module):
    def __init__(self, num_numeric, cat_cards, hidden_dim=192, num_heads=6,
                 num_blocks=2, dropout=0.2, num_classes=2):
        super().__init__()
        self.num_numeric = int(num_numeric)
        self.cat_cards = [int(c) for c in cat_cards]
        self.emb_dims = [min(8, max(3, int(round(1.6 * (c ** 0.56))))) for c in self.cat_cards]
        self.embs = nn.ModuleList([nn.Embedding(c, d) for c, d in zip(self.cat_cards, self.emb_dims)])
        self.emb_drop = nn.Dropout(0.1)
        in_dim = self.num_numeric + sum(self.emb_dims)
        self.num_heads = int(num_heads)
        self.num_classes = int(num_classes)
        self.input_proj = nn.Sequential(nn.Linear(in_dim, hidden_dim), nn.GELU(), nn.LayerNorm(hidden_dim))
        self.blocks = nn.ModuleList([TabMRank1Block(hidden_dim, num_heads, dropout) for _ in range(num_blocks)])
        self.W_out = nn.Parameter(torch.empty(num_heads, num_classes, hidden_dim))
        self.b_out = nn.Parameter(torch.zeros(num_heads, num_classes))
        for k in range(num_heads):
            nn.init.xavier_uniform_(self.W_out[k])

    def forward(self, x_num, x_cat):
        emb = [e(x_cat[:, i]) for i, e in enumerate(self.embs)]
        emb_cat = self.emb_drop(torch.cat(emb, dim=-1))
        x = torch.cat([x_num, emb_cat], dim=-1)
        h = self.input_proj(x).unsqueeze(0).expand(self.num_heads, -1, -1)
        for block in self.blocks:
            h = block(h)
        return torch.baddbmm(self.b_out.unsqueeze(1), h, self.W_out.transpose(-2, -1))


@torch.no_grad()
def predict_proba(model, x_num, x_cat, batch_size=None):
    model.eval()
    if batch_size is None or batch_size >= x_num.shape[0]:
        return torch.softmax(model(x_num, x_cat), dim=-1).mean(dim=0)
    chunks = []
    for s in range(0, x_num.shape[0], batch_size):
        chunks.append(torch.softmax(model(x_num[s:s+batch_size], x_cat[s:s+batch_size]), dim=-1).mean(dim=0))
    return torch.cat(chunks, dim=0)


# =========================================================================== #
# Step 3: training / CLI
# =========================================================================== #
NUM_FOLDS = 5
NUM_EPOCHS = 45
BATCH_SIZE = 512
LR = 1.5e-3
WEIGHT_DECAY = 1e-4
PATIENCE = 8
LABEL_SMOOTHING = 0.05
GRAD_CLIP = 1.0
DEVICE = torch.device("cpu")

MODEL_CONFIG = dict(hidden_dim=192, num_heads=6, num_blocks=2, dropout=0.2, num_classes=2)
HGB_CONFIG = dict(
    max_iter=800, learning_rate=0.05, max_leaf_nodes=31, min_samples_leaf=25,
    l2_regularization=0.1, early_stopping=True, validation_fraction=0.12,
    n_iter_no_change=25, random_state=42,
)
FEATURE_ENGINEER_FILE = "feature_engineer.pkl"
CAT_ENCODER_FILE = "cat_encoder.pkl"
ENSEMBLE_FILE = "tabm_ensemble.pt"
GBDT_FILE = "gbdt_ensemble.pkl"


def build_hgb(cat_mask, seed=0):
    from sklearn.ensemble import HistGradientBoostingClassifier
    kwargs = dict(HGB_CONFIG); kwargs["random_state"] = int(seed)
    mask = np.asarray(cat_mask, dtype=bool)
    if mask.size and bool(mask.any()):
        kwargs["categorical_features"] = mask.copy()
    return HistGradientBoostingClassifier(**kwargs)


def _train_one_fold(Xn_tr, Xc_tr, y_tr, Xn_va, Xc_va, y_va, cat_cards, seed):
    torch.manual_seed(int(seed)); np.random.seed(int(seed) % (2**31 - 1))
    xn_tr = torch.from_numpy(Xn_tr.astype(np.float32))
    xc_tr = torch.from_numpy(Xc_tr.astype(np.int64))
    yt = torch.from_numpy(y_tr.astype(np.int64))
    xn_va = torch.from_numpy(Xn_va.astype(np.float32))
    xc_va = torch.from_numpy(Xc_va.astype(np.int64))

    model = TabM(num_numeric=Xn_tr.shape[1], cat_cards=cat_cards, **MODEL_CONFIG).to(DEVICE)
    criterion = nn.CrossEntropyLoss(label_smoothing=LABEL_SMOOTHING)
    opt = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=NUM_EPOCHS)

    n = int(Xn_tr.shape[0])
    best_acc, best_state, bad = -1.0, {k: v.detach().clone() for k, v in model.state_dict().items()}, 0
    for epoch in range(NUM_EPOCHS):
        model.train()
        perm = np.random.permutation(n)
        for start in range(0, n, BATCH_SIZE):
            idx = perm[start:start + BATCH_SIZE]
            xb_n, xb_c, yb = xn_tr[idx], xc_tr[idx], yt[idx]
            logits = model(xb_n, xb_c)
            K, B, C = logits.shape
            loss = criterion(logits.reshape(K * B, C), yb.repeat(K))
            opt.zero_grad(); loss.backward()
            nn.utils.clip_grad_norm_(model.parameters(), GRAD_CLIP); opt.step()
        sched.step()
        model.eval()
        with torch.no_grad():
            pred = predict_proba(model, xn_va, xc_va, batch_size=1024).argmax(dim=-1).numpy()
        acc = float((pred == y_va).mean())
        if acc > best_acc + 1e-6:
            best_acc = acc
            best_state = {k: v.detach().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
        if bad >= PATIENCE:
            break
    model.load_state_dict(best_state)
    model.eval()
    return model, best_acc


def cmd_train(data_dir, model_dir):
    t0 = time.time()
    os.makedirs(model_dir, exist_ok=True)
    feats, y, schema = load_train_data(data_dir)
    y = np.asarray(y, dtype=np.int64)
    label_classes = list(schema["label_classes"])
    print(f"[train] n={len(y)} classes={label_classes} pos={float(y.mean()):.3f}")

    splits = get_cv_splits(y, NUM_FOLDS, 42)
    oof_mlp = np.zeros((len(y), len(label_classes)))
    oof_gb = np.zeros((len(y), len(label_classes)))
    fold_fes, fold_cats, fold_models = [], [], []
    fold_gb_encs, fold_gb_models = [], []
    cat_cards_global = None

    for fi, (tr, va) in enumerate(splits):
        print(f"[train] fold {fi+1}/{len(splits)}")
        ftr = feats.iloc[tr].reset_index(drop=True)
        fva = feats.iloc[va].reset_index(drop=True)
        fe = FeatureEngineer()
        Xn_tr = fe.fit_transform(ftr, y[tr]).to_numpy(dtype=np.float32)
        Xn_va = fe.transform(fva).to_numpy(dtype=np.float32)
        ce = CatEncoder().fit(ftr)
        Xc_tr = ce.transform(ftr)
        Xc_va = ce.transform(fva)
        cat_cards_global = list(ce.cards_)
        m, acc = _train_one_fold(Xn_tr, Xc_tr, y[tr], Xn_va, Xc_va, y[va], ce.cards_, 1000 + fi)
        p = predict_proba(m, torch.from_numpy(Xn_va), torch.from_numpy(Xc_va), 1024).numpy()
        oof_mlp[va] = p
        fold_fes.append(fe); fold_cats.append(ce); fold_models.append(m)

        gb_enc = GBDTFeatureEncoder().fit(ftr)
        gb_tr = gb_enc.transform(ftr); gb_va = gb_enc.transform(fva)
        gp = np.zeros((len(va), len(label_classes)))
        gms = []
        for s in (2000 + fi, 3000 + fi):
            gm = build_hgb(gb_enc.cat_mask_, s); gm.fit(gb_tr, y[tr])
            raw = gm.predict_proba(gb_va); cls = gm.classes_.astype(int)
            for ci, c in enumerate(cls):
                gp[:, c] += raw[:, ci]
            gms.append(gm)
        gp /= 2.0
        oof_gb[va] = gp
        fold_gb_encs.append(gb_enc); fold_gb_models.append(gms)
        print(f"[train]   mlp={acc:.4f} gbdt={float((gp.argmax(1)==y[va]).mean()):.4f}")

    mlp_acc = float((oof_mlp.argmax(1) == y).mean())
    gb_acc = float((oof_gb.argmax(1) == y).mean())
    best_w, best_acc = 0.5, -1.0
    for w in np.linspace(0.0, 1.0, 41):
        a = float(((w * oof_mlp + (1 - w) * oof_gb).argmax(1) == y).mean())
        if a > best_acc:
            best_acc, best_w = a, float(w)
    print(f"[train] OOF mlp={mlp_acc:.5f} gbdt={gb_acc:.5f} blend={best_acc:.5f} w_mlp={best_w:.3f}")

    with open(os.path.join(model_dir, FEATURE_ENGINEER_FILE), "wb") as fh:
        pickle.dump(fold_fes, fh, protocol=pickle.HIGHEST_PROTOCOL)
    with open(os.path.join(model_dir, CAT_ENCODER_FILE), "wb") as fh:
        pickle.dump(fold_cats, fh, protocol=pickle.HIGHEST_PROTOCOL)
    torch.save({
        "state_dicts": [m.state_dict() for m in fold_models],
        "num_numeric": int(Xn_tr.shape[1]),
        "cat_cards": cat_cards_global,
        "config": dict(MODEL_CONFIG),
        "label_classes": label_classes,
        "oof_blend_acc": float(best_acc),
    }, os.path.join(model_dir, ENSEMBLE_FILE))
    with open(os.path.join(model_dir, GBDT_FILE), "wb") as fh:
        pickle.dump({
            "encoders": fold_gb_encs, "models": fold_gb_models,
            "blend_weight": best_w, "label_classes": label_classes,
        }, fh, protocol=pickle.HIGHEST_PROTOCOL)
    print(f"[train] done {time.time()-t0:.1f}s  blend={best_acc:.5f}")
    return best_acc


def _restore_label(s):
    try: return int(s)
    except (TypeError, ValueError): pass
    try: return float(s)
    except (TypeError, ValueError): return s


def cmd_predict(data_dir, model_dir, output_path):
    t0 = time.time()
    with open(os.path.join(model_dir, FEATURE_ENGINEER_FILE), "rb") as fh:
        fold_fes = pickle.load(fh)
    with open(os.path.join(model_dir, CAT_ENCODER_FILE), "rb") as fh:
        fold_cats = pickle.load(fh)
    ckpt = torch.load(os.path.join(model_dir, ENSEMBLE_FILE), map_location="cpu", weights_only=False)
    label_classes = list(ckpt["label_classes"])
    num_numeric = int(ckpt["num_numeric"])
    config = dict(ckpt["config"])
    cat_cards = list(ckpt["cat_cards"])

    feats, _ = load_predict_data(data_dir)
    n = len(feats)
    C = config["num_classes"]
    proba = np.zeros((n, C))
    for fe, ce, sd in zip(fold_fes, fold_cats, ckpt["state_dicts"]):
        Xn = torch.from_numpy(fe.transform(feats).to_numpy(dtype=np.float32))
        Xc = torch.from_numpy(ce.transform(feats))
        m = TabM(num_numeric=num_numeric, cat_cards=cat_cards, **config)
        m.load_state_dict(sd); m.eval()
        proba += predict_proba(m, Xn, Xc, 1024).numpy()
    proba /= max(len(fold_fes), 1)

    blend_w = 1.0
    gb_path = os.path.join(model_dir, GBDT_FILE)
    if os.path.exists(gb_path):
        with open(gb_path, "rb") as fh:
            gb = pickle.load(fh)
        blend_w = float(gb.get("blend_weight", 1.0))
        gb_prob = np.zeros((n, C)); cnt = 0
        for enc, gms in zip(gb["encoders"], gb["models"]):
            gx = enc.transform(feats)
            for gm in (gms if isinstance(gms, list) else [gms]):
                raw = gm.predict_proba(gx); cls = gm.classes_.astype(int)
                for ci, c in enumerate(cls):
                    if 0 <= c < C: gb_prob[:, c] += raw[:, ci]
                cnt += 1
        gb_prob /= max(cnt, 1)
        proba = blend_w * proba + (1 - blend_w) * gb_prob

    pred_idx = proba.argmax(1)
    preds = [_restore_label(label_classes[int(i)]) for i in pred_idx]
    out = pd.DataFrame({"row_id": np.arange(len(preds), dtype=np.int64), "prediction": preds})
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    out.to_csv(output_path, index=False)
    print(f"[predict] {len(out)} rows -> {output_path} ({time.time()-t0:.1f}s)")


def main():
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    pt = sub.add_parser("train"); pt.add_argument("--data", required=True); pt.add_argument("--model", required=True)
    pp = sub.add_parser("predict"); pp.add_argument("--data", required=True); pp.add_argument("--model", required=True); pp.add_argument("--output", required=True)
    args = ap.parse_args()
    if args.cmd == "train":
        s = cmd_train(args.data, args.model)
        print(f"Final Validation Score: {s}")
    else:
        cmd_predict(args.data, args.model, args.output)


if __name__ == "__main__":
    main()
```

**Key improvements summary:**
- **Categorical embedding path** added to TabM: every nominal/freq/bin/interaction column is integer-encoded and passed through an `nn.Embedding`, concatenated with standardized numerics. This gives the MLP the right inductive bias for this low-cardinality categorical dataset.
- **8 TE sources** instead of 3 (coupon×{occupation, income, time, marital, direction, distance, expiration, age}), all fit OOF inside each fold — no leakage.
- **Expanded GBDT interaction set** (9 combinations) shares the same encoders, keeping the branch consistent.
- **Wider TabM** (hidden=192, 6 heads, dropout=0.2) plus blend grid over full [0,1] with OOF signal from both stronger branches.
- **No CLI changes**, everything persisted and reloaded read-only at predict; `row_id` = 0..N-1; prediction is the original label.
